/**
 * Full rollback watermark of a ratchet session (audit finding #2 follow-up).
 * `(pairing_epoch, ratchet_generation, send_message_count,
 * recv_message_count)` — lexicographically comparable. The send chain is
 * exactly as stateful as the recv chain (chain key + counter advance on every
 * `ratchet_encrypt`), so a live session that has sent MORE than a snapshot
 * contains must never be replaced by it: the send chain would roll back and
 * the derived message keys + (generation, seq) nonces would be reused for NEW
 * plaintext — the exact IV-reuse class the nonce-generation redesign
 * eliminates elsewhere. This record is the SINGLE watermark representation
 * shared by the UniFFI import guard, the UniFFI export surface and the store
 * restore paths, so the comparisons cannot drift.
 */
data class RatchetWatermark (
    var `pairingEpoch`: kotlin.ULong, 
    var `ratchetGeneration`: kotlin.UInt, 
    var `sendMessageCount`: kotlin.ULong, 
    var `recvMessageCount`: kotlin.ULong
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRatchetWatermark: FfiConverterRustBuffer<RatchetWatermark> {
    override fun read(buf: ByteBuffer): RatchetWatermark {
        return RatchetWatermark(
            FfiConverterULong.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: RatchetWatermark) = (
            FfiConverterULong.allocationSize(value.`pairingEpoch`) +
            FfiConverterUInt.allocationSize(value.`ratchetGeneration`) +
            FfiConverterULong.allocationSize(value.`sendMessageCount`) +
            FfiConverterULong.allocationSize(value.`recvMessageCount`)
    )

    override fun write(value: RatchetWatermark, buf: ByteBuffer) {
            FfiConverterULong.write(value.`pairingEpoch`, buf)
            FfiConverterUInt.write(value.`ratchetGeneration`, buf)
            FfiConverterULong.write(value.`sendMessageCount`, buf)
            FfiConverterULong.write(value.`recvMessageCount`, buf)
    }
}





sealed class KyberException: kotlin.Exception() {
    
    class CryptoException(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class KeyGenerationFailed(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class EncapsulationFailed(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class DecapsulationFailed(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class EncryptionFailed(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class DecryptionFailed(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SerializationException(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NetworkException(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SessionDesynchronized(
        
        val v1: kotlin.String
        ) : KyberException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidKeyLength(
        
        val `expected`: kotlin.ULong, 
        
        val `got`: kotlin.ULong
        ) : KyberException() {
        override val message
            get() = "expected=${ `expected` }, got=${ `got` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<KyberException> {
        override fun lift(error_buf: RustBuffer.ByValue): KyberException = FfiConverterTypeKyberError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeKyberError : FfiConverterRustBuffer<KyberException> {
    override fun read(buf: ByteBuffer): KyberException {
        

        return when(buf.getInt()) {
            1 -> KyberException.CryptoException(
                FfiConverterString.read(buf),
                )
            2 -> KyberException.KeyGenerationFailed(
                FfiConverterString.read(buf),
                )
            3 -> KyberException.EncapsulationFailed(
                FfiConverterString.read(buf),
                )
            4 -> KyberException.DecapsulationFailed(
                FfiConverterString.read(buf),
                )
            5 -> KyberException.EncryptionFailed(
                FfiConverterString.read(buf),
                )
            6 -> KyberException.DecryptionFailed(
                FfiConverterString.read(buf),
                )
            7 -> KyberException.SerializationException(
                FfiConverterString.read(buf),
                )
            8 -> KyberException.NetworkException(
                FfiConverterString.read(buf),
                )
            9 -> KyberException.SessionDesynchronized(
                FfiConverterString.read(buf),
                )
            10 -> KyberException.InvalidKeyLength(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: KyberException): ULong {
        return when(value) {
            is KyberException.CryptoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.KeyGenerationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.EncapsulationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.DecapsulationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.EncryptionFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.DecryptionFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.SerializationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.NetworkException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.SessionDesynchronized -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is KyberException.InvalidKeyLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`expected`)
                + FfiConverterULong.allocationSize(value.`got`)
            )
        }
    }

    override fun write(value: KyberException, buf: ByteBuffer) {
        when(value) {
            is KyberException.CryptoException -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.KeyGenerationFailed -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.EncapsulationFailed -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.DecapsulationFailed -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.EncryptionFailed -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.DecryptionFailed -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.SerializationException -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.NetworkException -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.SessionDesynchronized -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is KyberException.InvalidKeyLength -> {
                buf.putInt(10)
                FfiConverterULong.write(value.`expected`, buf)
                FfiConverterULong.write(value.`got`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




